def policy(obs,P):
 x,y,vx,vy,angle,ang_v,leg_left,leg_right=obs[0],obs[1],obs[2],obs[3],obs[4],obs[5],obs[6],obs[7]
 if (leg_left>0.5 or leg_right>0.5) and abs(vx)<P['vx_leg'] and abs(vy)<P['vy_leg'] and abs(angle)<P['ang_leg'] and abs(ang_v)<P['angv_leg']:
  return 0
 if y>P['y_high'] and vy<P['vy_very_neg']:
  return 0
 if y<P['y_emerg'] and vy<P['vy_emerg_thr']:
  return 2
 if vy<P['vy_strong'] and y<P['y_main_max']:
  return 2
 if angle>P['angle_thresh'] or ang_v>P['angv_thresh']:
  return 3
 if angle<-P['angle_thresh'] or ang_v<-P['angv_thresh']:
  return 1
 if x<-P['x_thresh'] or vx<-P['vx_thresh']:
  return 3
 if x>P['x_thresh'] or vx>P['vx_thresh']:
  return 1
 if y>P['y_high'] and vy<P['vy_main_high'] and vy>P['vy_very_neg']:
  return 2
 if vy<P['vy_main'] and y<P['y_main_max']:
  return 2
 if y<P['y_low'] and vy<P['vy_low']:
  return 2
 return 0
